WebLink.url:
{!requireScript("/soap/ajax/32.0/connection.js")}
{!requireScript("/support/console/32.0/integration.js")}


var asset = '{!User.Asset_Class__c}';
var accId = '{!Account.Id}';
var assetFieldID = '{!$Setup.Application_Settings_Hierarchy__c.OpportunityAssetClass_fieldID__c}';

var params = '&retURL=%2F';

if (accId != '') {
//alert('accId: ' + accId );
params  += accId + '&accid=' + accId ;
}else{
params += '006%2Fo';
}


if(asset != ''){
var a = asset.split(';');
//if(a.length==1){
if (a[0] == 'EQ'){
  a[0] = 'Cash Equity';
}
params += '&' + assetFieldID  + '=' + a[0];


//}
}
if (sforce.console.isInConsole()) {
   openSubTab('/006/e?' + params, 'New Opportunity', true);
}else{
  window.parent.location.assign('/006/e?' + params);
}



function openSubTab(url, title, refreshOnClose) {
	var refreshPrimaryTab = function() {
		sforce.console.getEnclosingPrimaryTabId(function(result) {
			sforce.console.refreshPrimaryTabById(result.id, true);
		});
	}

	sforce.console.getEnclosingPrimaryTabId(function(result) {
		var primaryTabId = result.id;
if (primaryTabId  != null){
		sforce.console.openSubtab(primaryTabId, url, true, title, null, function(r) {
			if (refreshOnClose)
				sforce.console.addEventListener(sforce.console.ConsoleEvent.CLOSE_TAB,
					refreshPrimaryTab, {tabId: r.id});
		});
}else{
//srcUp(url);
sforce.console.openPrimaryTab(null, url, true, 'New Opportunity');
}
	});
}
